<?php use App\Support\App;$u=App::requireAuth();$q=App::db()->prepare('SELECT p.*,pp.price FROM products p JOIN product_prices pp ON pp.product_id=p.id AND pp.level_id=? WHERE p.is_active=1 ORDER BY p.sort_order,p.name');$q->execute([$u['level_id']]);$rows=$q->fetchAll();$title='Services';require __DIR__.'/../layouts/head.php';require __DIR__.'/../components/app_start.php';?><div><h1 class="page-title">Services</h1><p class="page-sub">Daftar layanan dan harga khusus level <?=htmlspecialchars($u['level_code']??'user')?>.</p></div><div class="grid sm:grid-cols-2 xl:grid-cols-3 gap-4 mt-6"><?php foreach($rows as $p):?><div class="saas-card p-5"><div class="flex justify-between gap-3"><span class="badge"><?=htmlspecialchars($p['provider_type'])?></span><span class="badge"><?=$p['ceir_check_enabled']?'CEIR ON':'CEIR OFF'?></span></div><h2 class="font-semibold text-lg mt-4"><?=htmlspecialchars($p['name'])?></h2><p class="text-sm text-zinc-500 mt-2 min-h-10"><?=htmlspecialchars($p['description']??'')?></p><div class="text-2xl font-bold mt-5">Rp<?=number_format($p['price'],0,',','.')?></div><div class="text-xs text-zinc-500 mt-1"><?=htmlspecialchars($p['processing_time']?:'Processing time varies')?></div><a href="/order" class="btn btn-dark w-full mt-5">Order service</a></div><?php endforeach?><?php if(!$rows):?><div class="saas-card p-10 text-zinc-500">Belum ada layanan aktif untuk level akun Anda.</div><?php endif?></div><?php require __DIR__.'/../components/app_end.php';require __DIR__.'/../layouts/foot.php';?>